param([string]$Revision='0.1.0-dev.1')
$ErrorActionPreference='Stop';$files=Get-ChildItem target -File|Where-Object{$_.Name -in @("madlava-agent-$Revision.jar","madlava-report-viewer-$Revision.zip","madlava-$Revision-complete-project.zip","madlava-agent-$Revision-example.jar")}|Sort-Object Name;if($files.Count-ne4){throw 'Expected four I01 artifacts'};$lines=$files|ForEach-Object{"$((Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower())  $($_.Name)"};$path="target/MadLava-$Revision-SHA256SUMS.txt";[IO.File]::WriteAllLines((Join-Path(Get-Location)$path),$lines,(New-Object Text.UTF8Encoding($false)));Write-Output $path
